    fields=dict(actualExit=0,source=original.SOURCE,originalManifestSha256=RAW[1],tests=4,suites=1,newTestIds=0,cases=raw['cases'],targetSourceUnits=1,completeSourceUnitClosure={n:sorted(v) for n,v in original.CLOSURES.items()},metadataClasses=sorted(original.METADATA),unexecutedCodeClasses=[],totals=totals,strictFour100GateExit=1,targetUnitFour100=False,allMeasuredApplicableCountersCovered=False,singleSession=True,crcMismatch=0,manualCounterExclusions=[],cryptoOrKeyOperationsInvoked=False,publicDigestOnly=False,publicSyntheticUuidFixture=False,ownThreadCount=2,declaredOwnExecutorInstances=2,declaredOwnTaskCount=2,syntheticJdbcPortsOnly=False,syntheticJdbcApiCallsInvoked=False,uninstalledSelfOwnedLifetimeOnly=True,actualHookRegistrationOrRemovalInvoked=False,actualNativeHookOrProviderOperation=False,declaredOwnUnstartedHookThreadObjects=4,bug1743ActualHookHoldRetained=True,actualSecretKeysLoaded=False,actualJdbcBackendConnected=False,actualSqlStatementsPreparedOrExecuted=0,actualJmsConnectionsCreated=0,actualRootRecoveryOperations=0,actualFilesOpenedByProduct=False,actualPermitIssueSignPublishOrRetire=False,wholePrior27AbsenceClaimed=False,approvedInjectedBackupCycleOnly=False,syntheticArchiveCallbacksInvoked=False,syntheticRetirementCallbacksInvoked=False,formalUpdated=False,whole451Accepted=False,oldCoverageTransferred=False,effortPercent=None)
